//! Golden parity: `rune/parity/fixtures/classic.json` (generated by
//! `rune/parity/ts/classic.golden.ts` from the TypeScript DSP).
//!
//! Primitives are compared on full vectors. Every voice of every machine must be bit-exact over
//! its full length: an FNV-1a 64 digest of the little-endian f32 bytes is compared
//! (`every_voice_is_bit_exact`). For diagnostics, the exact length, peak / RMS / sum and ~128
//! samples (64 evenly spaced + first 32 + last 32) are compared too, which locate an error.

use super::dsp::*;
use super::*;
use mdaw_model::classic_meta::CLASSIC_MACHINES;
use serde_json::Value;

/// Per-sample tolerance against the TS render (libm ulp drift; JS math is V8's fdlibm port).
const SAMPLE_TOL: f64 = 1e-5;
/// RMS relative tolerance.
const RMS_TOL: f64 = 1e-5;

fn fixture() -> &'static Value {
    static FX: OnceLock<Value> = OnceLock::new();
    FX.get_or_init(|| {
        serde_json::from_str(include_str!("../../../../parity/fixtures/classic.json")).unwrap()
    })
}

fn f64s(v: &Value) -> Vec<f64> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|x| x.as_f64().unwrap())
        .collect()
}

/// Max |got - want|; panics on a length mismatch.
fn max_diff(label: &str, got: &[f32], want: &Value) -> f64 {
    let want = f64s(want);
    assert_eq!(got.len(), want.len(), "{label}: length");
    got.iter()
        .zip(&want)
        .map(|(&g, &w)| (g as f64 - w).abs())
        .fold(0.0, f64::max)
}

fn check(label: &str, got: &[f32], want: &Value) -> f64 {
    let d = max_diff(label, got, want);
    println!("{label:<40} max |diff| = {d:.3e}");
    assert!(
        d <= SAMPLE_TOL,
        "{label}: max |diff| {d:e} > {SAMPLE_TOL:e}"
    );
    d
}

fn env_opts(v: &Value) -> EnvOpts {
    let g = |k: &str, d: f64| v.get(k).and_then(Value::as_f64).unwrap_or(d);
    EnvOpts {
        attack: g("attack", EnvOpts::D.attack),
        hold: g("hold", 0.0),
        t60: g("t60", 0.0),
        delay: g("delay", 0.0),
    }
}

fn osc_opts(v: &Value) -> OscOpts {
    let g = |k: &str, d: f64| v.get(k).and_then(Value::as_f64).unwrap_or(d);
    let d = OscOpts::D;
    OscOpts {
        freq: g("freq", 0.0),
        sweep: g("sweep", d.sweep),
        sweep_tau: g("sweepTau", d.sweep_tau),
        sweep2: g("sweep2", d.sweep2),
        sweep2_tau: g("sweep2Tau", d.sweep2_tau),
        drift: g("drift", d.drift),
        shape: if v.get("shape").and_then(Value::as_str) == Some("tri") {
            Shape::Tri
        } else {
            Shape::Sine
        },
        phase: g("phase", d.phase),
    }
}

/// Same as the TS `testSignal`.
fn test_signal(n: usize) -> Vec<f32> {
    let a = osc(
        n,
        OscOpts {
            freq: 440.0,
            sweep: 0.5,
            sweep_tau: 0.01,
            ..OscOpts::D
        },
    );
    let b = osc(
        n,
        OscOpts {
            freq: 3100.0,
            phase: 0.3,
            ..OscOpts::D
        },
    );
    let z = noise(n, 99);
    let e = env(n, EnvOpts::t60((n as f64 / SR) * 0.8));
    (0..n)
        .map(|i| ((a[i] as f64 * 0.6 + b[i] as f64 * 0.3 + z[i] as f64 * 0.2) * e[i] as f64) as f32)
        .collect()
}

#[test]
fn constants() {
    let fx = fixture();
    assert_eq!(fx["sr"].as_f64().unwrap(), SR);
    assert_eq!(fx["targetPeak"].as_f64().unwrap(), target_peak());
}

#[test]
fn rng_sequences_are_exact() {
    for (seed, want) in fixture()["rng"].as_object().unwrap() {
        let mut r = Rng::new(seed.parse::<u64>().unwrap() as u32);
        let got: Vec<f64> = (0..64).map(|_| r.next_f64()).collect();
        assert_eq!(got, f64s(want), "seed {seed}");
    }
    let got = noise(64, 5);
    assert_eq!(max_diff("noise", &got, &fixture()["noise"]), 0.0);
}

#[test]
fn envelopes() {
    let fx = fixture();
    for (i, c) in fx["envs"].as_array().unwrap().iter().enumerate() {
        check(
            &format!("env[{i}]"),
            &env(600, env_opts(&c["opts"])),
            &c["out"],
        );
    }
    let s = env_sum(
        600,
        &[
            (
                0.72,
                EnvOpts {
                    attack: 0.0005,
                    ..EnvOpts::t60(0.007)
                },
            ),
            (
                0.28,
                EnvOpts {
                    attack: 0.0005,
                    ..EnvOpts::t60(0.04)
                },
            ),
        ],
    );
    check("envSum", &s, &fx["envSum"]);
    let c = clap_env(
        1200,
        &ClapEnvOpts {
            bursts: &[0.0, 0.0065, 0.017],
            burst_t60: 0.018,
            tail_delay: 0.017,
            tail_t60: 0.03,
            tail_gain: 0.5,
        },
    );
    check("clapEnv", &c, &fx["clapEnv"]);
}

#[test]
fn oscillators() {
    let fx = fixture();
    for (i, c) in fx["oscs"].as_array().unwrap().iter().enumerate() {
        check(
            &format!("osc[{i}]"),
            &osc(512, osc_opts(&c["opts"])),
            &c["out"],
        );
    }
    for c in fx["squares"].as_array().unwrap() {
        let (f, p) = (c["freq"].as_f64().unwrap(), c["phase"].as_f64().unwrap());
        check(&format!("square {f} {p}"), &square(512, f, p), &c["out"]);
    }
    check(
        "metal",
        &metal(256, &[205.3, 304.4, 369.6, 522.7, 540.0, 800.0], 11),
        &fx["metal"],
    );
    check(
        "partials",
        &partials(
            256,
            &[(3170.0, 1.0, 1.4), (4650.0, 0.6, 1.0), (5980.0, 0.4, 0.8)],
            PARTIALS_ATTACK,
        ),
        &fx["partials"],
    );
}

#[test]
fn filters_and_shaping() {
    let fx = fixture();
    for c in fx["biquads"].as_array().unwrap() {
        let ty = match c["type"].as_str().unwrap() {
            "lp" => FilterType::Lp,
            "hp" => FilterType::Hp,
            "bp" => FilterType::Bp,
            _ => FilterType::Peak,
        };
        let freq = c["freq"].as_f64().unwrap();
        let q = c.get("q").and_then(Value::as_f64).unwrap_or(DEFAULT_Q);
        let gain = c.get("gainDb").and_then(Value::as_f64).unwrap_or(0.0);
        let input = if c["input"] == "step" {
            vec![1.0f32; 256]
        } else {
            test_signal(256)
        };
        let label = format!("biquad {} {freq} {q} {gain} {}", c["type"], c["input"]);
        check(&label, &biquad(input, ty, freq, q, gain), &c["out"]);
    }
    let dc: Vec<f32> = test_signal(256)
        .iter()
        .map(|&x| (x as f64 + 0.3) as f32)
        .collect();
    check("dcBlock", &dc_block(dc, 10.0), &fx["dcBlock"]);
    for c in fx["lofis"].as_array().unwrap() {
        let o = &c["opts"];
        let opts = LofiOpts {
            rate: o.get("rate").and_then(Value::as_f64).unwrap_or(SR),
            bits: o["bits"].as_i64().unwrap() as i32,
            mu: o.get("mu").and_then(Value::as_bool).unwrap_or(false),
        };
        check(
            &format!("lofi {o}"),
            &lofi(test_signal(1000), opts),
            &c["out"],
        );
    }
    for c in fx["drives"].as_array().unwrap() {
        let amount = c["amount"].as_f64().unwrap();
        check(
            &format!("drive {amount}"),
            &drive(test_signal(256), amount),
            &c["out"],
        );
    }
    check(
        "drive silent",
        &drive(vec![0.0; 8], 2.0),
        &fx["driveSilent"],
    );
    check(
        "finalize",
        &finalize(
            &test_signal(4000),
            FinalizeOpts {
                max_sec: 0.08,
                ..FinalizeOpts::D
            },
        ),
        &fx["finalize"],
    );
}

/// Per-voice comparison result.
struct VoiceErr {
    label: String,
    max_sample: f64,
    rms_rel: f64,
}

fn compare_voice(v: &Value) -> VoiceErr {
    let machine = ClassicMachineId::from_id(v["machine"].as_str().unwrap()).unwrap();
    let voice = v["voice"].as_str().unwrap();
    let label = format!("{}/{voice}", machine.id());
    let data = synthesize_classic_voice(machine, voice).unwrap();
    let len = v["len"].as_u64().unwrap() as usize;
    assert_eq!(data.len(), len, "{label}: length");
    let mut max_sample = 0.0f64;
    for (&i, w) in f64s(&v["idx"]).iter().zip(f64s(&v["at"])) {
        max_sample = max_sample.max((data[i as usize] as f64 - w).abs());
    }
    max_sample = max_sample.max(max_diff(&label, &data[..32.min(len)], &v["first"]));
    max_sample = max_sample.max(max_diff(
        &label,
        &data[len.saturating_sub(32)..],
        &v["last"],
    ));
    let (mut peak, mut sq, mut sum) = (0.0f64, 0.0f64, 0.0f64);
    for &x in &data {
        let x = x as f64;
        peak = peak.max(x.abs());
        sq += x * x;
        sum += x;
    }
    let rms = (sq / len as f64).sqrt();
    let want_rms = v["rms"].as_f64().unwrap();
    let rms_rel = (rms - want_rms).abs() / want_rms;
    max_sample = max_sample.max((peak - v["peak"].as_f64().unwrap()).abs());
    // The sum of up to ~100k samples: allow the per-sample tolerance to accumulate.
    let sum_diff = (sum - v["sum"].as_f64().unwrap()).abs();
    assert!(
        sum_diff <= SAMPLE_TOL * len as f64,
        "{label}: sum differs by {sum_diff:e}"
    );
    VoiceErr {
        label,
        max_sample,
        rms_rel,
    }
}

#[test]
fn every_voice_matches_the_typescript_render() {
    let voices = fixture()["voices"].as_array().unwrap();
    let total: usize = CLASSIC_MACHINES.iter().map(|m| m.voices.len()).sum();
    assert_eq!(
        voices.len(),
        total,
        "fixture covers every voice of every machine"
    );
    let mut errs: Vec<VoiceErr> = voices.iter().map(compare_voice).collect();
    errs.sort_by(|a, b| b.max_sample.total_cmp(&a.max_sample));
    for e in &errs {
        println!(
            "{:<24} max |diff| = {:.3e}   rms rel = {:.3e}",
            e.label, e.max_sample, e.rms_rel
        );
    }
    let bad: Vec<String> = errs
        .iter()
        .filter(|e| e.max_sample > SAMPLE_TOL || e.rms_rel > RMS_TOL)
        .map(|e| format!("{} ({:e}, rms {:e})", e.label, e.max_sample, e.rms_rel))
        .collect();
    assert!(bad.is_empty(), "voices outside tolerance: {bad:?}");
}

/// FNV-1a 64.
fn fnv1a64(bytes: impl IntoIterator<Item = u8>) -> u64 {
    bytes.into_iter().fold(0xcbf2_9ce4_8422_2325, |h, b| {
        (h ^ u64::from(b)).wrapping_mul(0x0000_0100_0000_01b3)
    })
}

/// FNV-1a 64 over the little-endian f32 bytes, as hex (mirrors `fnv1a64` in `classic.golden.ts`).
fn fnv1a64_f32(data: &[f32]) -> String {
    format!(
        "{:016x}",
        fnv1a64(data.iter().flat_map(|x| x.to_le_bytes()))
    )
}

#[test]
fn fnv1a64_known_vectors() {
    assert_eq!(fnv1a64(*b""), 0xcbf2_9ce4_8422_2325);
    assert_eq!(fnv1a64(*b"a"), 0xaf63_dc4c_8601_ec8c);
    assert_eq!(fnv1a64(*b"foobar"), 0x8594_4171_f739_67e8);
}

/// Full-length bit-exactness of all 97 voices: digest of the whole Rust render vs the digest of
/// the whole TS render. Any flipped bit in any sample fails this test.
#[test]
fn every_voice_is_bit_exact() {
    let voices = fixture()["voices"].as_array().unwrap();
    let total: usize = CLASSIC_MACHINES.iter().map(|m| m.voices.len()).sum();
    assert_eq!(voices.len(), total);
    let mut bad = Vec::new();
    for v in voices {
        let machine = ClassicMachineId::from_id(v["machine"].as_str().unwrap()).unwrap();
        let voice = v["voice"].as_str().unwrap();
        let data = synthesize_classic_voice(machine, voice).unwrap();
        let want = v["fnv1a64"]
            .as_str()
            .expect("fnv1a64 digest in classic.json");
        let got = fnv1a64_f32(&data);
        if got != want || data.len() as u64 != v["len"].as_u64().unwrap() {
            bad.push(format!(
                "{}/{voice}: len {} vs {}, fnv1a64 {got} vs {want}",
                machine.id(),
                data.len(),
                v["len"]
            ));
        }
    }
    println!(
        "{} of {total} voices bit-exact over their full length",
        total - bad.len()
    );
    assert!(bad.is_empty(), "voices not bit-exact: {bad:?}");
}

/// Spectral metrics of `analysis.ts` on the TS render vs ours.
#[test]
fn voice_analysis_matches() {
    for v in fixture()["voices"].as_array().unwrap() {
        let machine = ClassicMachineId::from_id(v["machine"].as_str().unwrap()).unwrap();
        let voice = v["voice"].as_str().unwrap();
        let a = analyze_voice(&synthesize_classic_voice(machine, voice).unwrap(), SR);
        let w = &v["analysis"];
        let close = |got: f64, k: &str, tol: f64| {
            let want = w[k].as_f64().unwrap();
            assert!(
                (got - want).abs() <= tol * want.abs().max(1.0),
                "{machine:?}/{voice} {k}: {got} vs {want}"
            );
        };
        close(a.centroid_hz, "centroidHz", 1e-6);
        close(a.low_frac, "lowFrac", 1e-6);
        close(a.high_frac, "highFrac", 1e-6);
        close(a.peak_hz, "peakHz", 0.0);
    }
}

/// Full-length comparison against raw `.f32` dumps (`CLASSIC_DUMP_DIR=<dir>` when running the
/// golden script). Diagnostics only: `CLASSIC_DUMP_DIR=<dir> cargo test -p mdaw-dsp -- --ignored
/// full_dump --nocapture`.
#[test]
#[ignore]
fn full_dump() {
    let Ok(dir) = std::env::var("CLASSIC_DUMP_DIR") else {
        return;
    };
    let mut rows = Vec::new();
    for m in &CLASSIC_MACHINES {
        for v in m.voices {
            let bytes = std::fs::read(format!("{dir}/{}_{}.f32", m.id.id(), v.id)).unwrap();
            let want: Vec<f32> = bytes
                .as_chunks::<4>()
                .0
                .iter()
                .map(|b| f32::from_le_bytes(*b))
                .collect();
            let got = synthesize_classic_voice(m.id, v.id).unwrap();
            assert_eq!(got.len(), want.len());
            let mut d = 0.0f64;
            let mut exact = 0usize;
            for (g, w) in got.iter().zip(&want) {
                d = d.max((*g as f64 - *w as f64).abs());
                exact += usize::from(g.to_bits() == w.to_bits());
            }
            rows.push((
                format!("{}/{}", m.id.id(), v.id),
                d,
                exact as f64 / got.len() as f64,
            ));
        }
    }
    rows.sort_by(|a, b| b.1.total_cmp(&a.1));
    for (l, d, e) in rows {
        println!("{l:<24} max |diff| = {d:.3e}  bit-exact {:.2}%", e * 100.0);
    }
}
